"""Machine-drafted translations; native review remains mandatory."""
from pathlib import Path
import csv

ROOT=Path(__file__).resolve().parents[1]
with (ROOT/'localization/strings.csv').open(encoding='utf-8-sig',newline='') as f:
    reader=csv.DictReader(f)
    locales=reader.fieldnames[1:]
    rows={row['keys']:row for row in reader}

def group(keys, data):
    keys=keys.split('|')
    for locale, text in data.items():
        values=text.split('|')
        if len(values)!=len(keys): raise ValueError(f'{locale}: {len(values)} values, expected {len(keys)} for {keys[0]}')
        for key,value in zip(keys,values): rows[key][locale]=value

