perfect=['Perfect','Kusursuz','Perfecto','Perfeito','Parfait','Perfekt','Perfetto','全消し','전체 지우기','全消','كامل','पूर्ण','Sempurna','Xóa sạch','Полная очистка','สมบูรณ์แบบ']
close=['Close','Kapat','Cerrar','Fechar','Fermer','Schließen','Chiudi','閉じる','닫기','关闭','إغلاق','बंद करें','Tutup','Đóng','Закрыть','ปิด']
for index,locale in enumerate(locales):
    if locale=='en': continue
    for target,source in aliases.items(): rows[target][locale]=rows[source][locale]
    rows['app.name'][locale]='LumiBlock'
    rows['over.best'][locale]=rows['game.best'][locale]+': {n}'
    rows['reset.title'][locale]=rows['settings.reset'][locale]+'?'
    rows['game.perfect'][locale]=perfect[index]
    rows['common.close'][locale]=close[index]
    rows['date.pattern'][locale]='{d} {month} {y}'
    if locale in ['ja','zh-CN']: rows['date.pattern'][locale]='{y}年{month}{d}日'
    elif locale=='ko': rows['date.pattern'][locale]='{y}년 {month} {d}일'
    elif locale=='en': rows['date.pattern'][locale]='{month} {d}, {y}'
    for month,value in enumerate(months[locale].split(),1): rows[f'month.{month}'][locale]=value.replace('-', ' ') if locale=='vi' else value

with (ROOT/'localization/strings.csv').open('w',encoding='utf-8',newline='') as f:
    writer=csv.writer(f)
    writer.writerow(['keys']+locales)
    for key,row in rows.items(): writer.writerow([key]+[row[locale] for locale in locales])
print(f'Completed {len(rows)} keys × {len(locales)} locales; machine-drafted, native review required')
